//! ====================================================================
//!  Rust Tree CLI Utility for Windows
//!  Generated by Rust Tree Command Builder
//! ====================================================================
//!
//!  このプログラムは、指定したディレクトリの構造をツリー形式で出力するCLIツールです。
//!  外部の重いライブラリ（clapなど）に依存せず、Rustの標準ライブラリ（std）のみで
//!  軽量・高速に動作するように記述されています。

mod config;
mod icon;
mod serializer;
mod tree;
mod util;

use config::{parse_arguments, print_help, OutputFormat, TreeConfig};
use serializer::{build_tree_node, serialize_json, serialize_xml};
use std::env;
use tree::{build_dir_summary_map, format_root_line, print_tree};

fn main() {
    // Windows 10/11のプロンプトでANSIエスケープカラーを有効化
    #[cfg(windows)]
    enable_ansi_support();

    // 1. 引数の解析
    let args: Vec<String> = env::args().collect();
    let mut config = TreeConfig::default();

    if let Err(err) = parse_arguments(&args, &mut config) {
        eprintln!("【エラー】: {}", err);
        print_help();
        std::process::exit(1);
    }

    // ターゲットが存在するか検証
    if !config.target_path.exists() {
        eprintln!(
            "【エラー】: 指定されたパスが存在しません: {:?}",
            config.target_path
        );
        std::process::exit(1);
    }

    // 2. 出力処理の分岐
    match config.output_format {
        OutputFormat::Text => {
            let summary_map = if config.show_dir_sizes {
                Some(build_dir_summary_map(&config.target_path, &config))
            } else {
                None
            };

            println!("{}", format_root_line(&config, summary_map.as_ref()));

            let mut dir_count = 0;
            let mut file_count = 0;

            // 再帰的にツリーを描画
            print_tree(
                &config.target_path,
                0,
                &mut Vec::new(),
                &config,
                &mut dir_count,
                &mut file_count,
                summary_map.as_ref(),
            );

            // 最終集計の出力
            println!();
            if config.classic_mode {
                println!("{} directories, {} files", dir_count, file_count);
            } else {
                println!(
                    "\x1b[36m{} directories, {} files\x1b[0m",
                    dir_count, file_count
                );
            }
        }
        OutputFormat::Json => {
            let mut dir_count = 0;
            let mut file_count = 0;
            let root = build_tree_node(
                &config.target_path,
                0,
                &config,
                &mut dir_count,
                &mut file_count,
            );
            println!("{}", serialize_json(&root, dir_count, file_count));
        }
        OutputFormat::Xml => {
            let mut dir_count = 0;
            let mut file_count = 0;
            let root = build_tree_node(
                &config.target_path,
                0,
                &config,
                &mut dir_count,
                &mut file_count,
            );
            println!("{}", serialize_xml(&root, dir_count, file_count));
        }
    }
}

/// Windows 10/11 コンソールで ANSI エスケープ処理を有効化する
#[cfg(windows)]
fn enable_ansi_support() {
    // Windows APIを動的にロードしてコンソールのモードを書き換える
    // 依存関係を増やさないよう、libc や winapi クレートを使わずに実装
    #[allow(clippy::upper_case_acronyms)]
    type LPDWORD = *mut u32;
    #[allow(clippy::upper_case_acronyms)]
    type HANDLE = *mut std::ffi::c_void;

    const STD_OUTPUT_HANDLE: u32 = -11i32 as u32;
    const ENABLE_VIRTUAL_TERMINAL_PROCESSING: u32 = 0x0004;

    #[link(name = "kernel32")]
    extern "system" {
        fn GetStdHandle(nStdHandle: u32) -> HANDLE;
        fn GetConsoleMode(hConsoleHandle: HANDLE, lpMode: LPDWORD) -> i32;
        fn SetConsoleMode(hConsoleHandle: HANDLE, dwMode: u32) -> i32;
    }

    unsafe {
        let handle = GetStdHandle(STD_OUTPUT_HANDLE);
        if !handle.is_null() {
            let mut mode: u32 = 0;
            if GetConsoleMode(handle, &mut mode as LPDWORD) != 0 {
                SetConsoleMode(handle, mode | ENABLE_VIRTUAL_TERMINAL_PROCESSING);
            }
        }
    }
}
